script:
(function () {
  'use strict';
  // Loan prequalification from a debt-to-income (DTI) limit.
  //   Room for the new payment = DTI% x gross monthly income - (housing + other debt payments).
  //   Maximum loan = room x (1 - (1 + i)^-n) / i, i = APR / 12, n = term in months (room x n at 0%).
  //   Payment on a requested amount L = L x i / (1 - (1 + i)^-n); DTI with it = (debts + payment) / income.
  // Verified (Node, scratchpad tests/g1031_lpq.test.js) against an independent calculation:
  //   $72,000 income, $1,900 current debts, 40% limit -> $500/month room; at 11% for 60 months the
  //   maximum loan is $22,996.52; $20,000 at 11% for 60 months costs $434.85/month (standard
  //   amortization), DTI 38.9%; 0% for 60 months -> $30,000 max; debts above the limit give $0.
  //   Blank or invalid input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct1 = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function maxLoan(payment, apr, months) {
    if (!(payment > 0) || !(months > 0)) return 0;
    var i = apr / 100 / 12;
    if (i === 0) return payment * months;
    return payment * (1 - Math.pow(1 + i, -months)) / i;
  }
  function payment(loan, apr, months) {
    if (!(loan > 0) || !(months > 0)) return 0;
    var i = apr / 100 / 12;
    if (i === 0) return loan / months;
    return loan * i / (1 - Math.pow(1 + i, -months));
  }

  var IDS = ['lpqMax', 'lpqMaxPay', 'lpqWantPay', 'lpqWantDti', 'lpqVerdict', 'lpqMonthly', 'lpqCap', 'lpqCurrent', 'lpqRoom', 'lpqNowDti'];

  function update() {
    var income = read('lpqIncome'), housing = read('lpqHousing', true), debts = read('lpqDebts', true), dti = read('lpqDti'),
        rate = read('lpqRate'), term = read('lpqTerm'), want = read('lpqWant', true);
    var err = el('lpqError'), msg = '';
    if (isNaN(income) || income <= 0 || income > 1e10) msg = 'Enter your gross annual income.';
    else if (isNaN(housing) || isNaN(debts) || housing < 0 || debts < 0) msg = 'Monthly payments cannot be negative.';
    else if (isNaN(dti) || dti <= 0 || dti > 100) msg = 'Enter a debt-to-income limit from 1% to 100%.';
    else if (isNaN(rate) || rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (isNaN(term) || term < 1 || term > 480 || Math.round(term) !== term) msg = 'Enter a loan term of 1 to 480 whole months.';
    else if (isNaN(want) || want < 0 || want > 1e10) msg = 'The amount you want to borrow cannot be negative.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { IDS.forEach(function (id) { setText(id, '–'); }); el('lpqGrid').innerHTML = ''; return; }

    var mInc = income / 12, current = housing + debts, cap = dti / 100 * mInc, room = Math.max(0, cap - current);
    var max = maxLoan(room, rate, term);
    setText('lpqMax', money0.format(max));
    setText('lpqMaxPay', money.format(room));
    setText('lpqMonthly', money.format(mInc));
    setText('lpqCapLabel', 'Debt limit (' + dti + '% of income)');
    setText('lpqCap', money.format(cap));
    setText('lpqCurrent', '−' + money.format(current));
    setText('lpqRoom', money.format(room));
    setText('lpqNowDti', pct1.format(current / mInc));

    var verdict;
    if (want > 0) {
      var p = payment(want, rate, term), newDti = (current + p) / mInc;
      setText('lpqWantPay', money.format(p));
      setText('lpqWantDti', pct1.format(newDti));
      if (p <= room + 0.005) verdict = 'You are likely to prequalify for ' + money0.format(want) + ': it keeps your debt-to-income ratio at ' +
        pct1.format(newDti) + ', within the ' + dti + '% limit, with ' + money.format(room - p) + ' a month to spare.';
      else verdict = money0.format(want) + ' would push your debt-to-income ratio to ' + pct1.format(newDti) + ', above the ' + dti +
        '% limit. Borrowing up to ' + money0.format(max) + ', choosing a longer term or paying down other debt would bring it within the limit.';
    } else {
      setText('lpqWantPay', '–');
      setText('lpqWantDti', '–');
      verdict = room > 0 ? 'Your current debts leave ' + money.format(room) + ' a month for a new loan payment under a ' + dti + '% limit.' :
        'Your current debts already use the whole ' + dti + '% limit, so a lender using it would not approve more borrowing.';
    }
    if (room <= 0 && want > 0) verdict = 'Your current debt payments already use the whole ' + dti + '% limit, so there is no room for a new loan payment. Paying down debt or a lender with a higher limit would change this.';
    setText('lpqVerdict', verdict);
    el('lpqVerdictBox').className = 'callout mt-5 ' + (want > 0 && payment(want, rate, term) > room + 0.005 ? 'callout-warning' : 'callout-note');

    var limits = [30, 36, 40, 43, 45, 50];
    if (limits.indexOf(dti) === -1) { limits.push(dti); limits.sort(function (a, b) { return a - b; }); }
    el('lpqGrid').innerHTML = limits.map(function (l) {
      var r = Math.max(0, l / 100 * mInc - current);
      return '<tr><td>' + l + '%' + (l === dti ? ' (yours)' : '') + '</td><td>' + money0.format(maxLoan(r, rate, 36)) + '</td><td>' +
        money0.format(maxLoan(r, rate, 60)) + '</td><td>' + money0.format(maxLoan(r, rate, 84)) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lpqForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
